    async def create_module(
        self,
        *,
        module_id: int,
        service_name: str,
        admin_name: str | None = None,
        admin_password: str | None = None,
        dependencies: list[HostingWebModuleDependencyType] | None = None,
        domain: str | None = None,
        language: HostingWebModuleLanguageEnum | None = None,
        path: str | None = None,
    ) -> HostingWebTask:
        """
        POST /1.0/hosting/web/{serviceName}/module

        Install a module

        Args:
            admin_name: The login for the admin account (may be a standard string or
                your email)
            admin_password: The password for the admin account (at least 8 characters)
            dependencies: The dependencies that we have to configure on your module. A
                dependency can be a standard database (like MySQL or PostgreSQL) or a
                key-value store (like Redis or Memcached) for example
            domain: On which domain the module has to be available (it can be a
                multidomain or a subdomain) - if not set, the module will be available
                on your serviceName domain
            language: The language to set to your module
            module_id: ID of the module you want to install
            path: Where to install the module, relative to your home directory
            service_name: The internal name of your hosting
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/1.0/hosting/web/{serviceName}/module", serviceName=service_name
            ),
            body={
                "adminName": admin_name,
                "adminPassword": admin_password,
                "dependencies": dependencies,
                "domain": domain,
                "language": language,
                "moduleId": module_id,
                "path": path,
            },
        )
        return HostingWebTask.model_validate(data)

